existingPatterns.pattern:
Rotas registradas em src/api/server.ts com padrão:
if (method === 'POST' && pathname === '/api/rota') { handler(req, res); return; }
Autenticação via função auxiliar existente: verifyJWT(req) → { userId, tenantId, role }
Admin: verificar perfil via checkAdminRole(req) → lança 403 se não for admin/operador

import { supabase } from '../lib/supabase';           // client público (respeita RLS)
import { supabaseAdmin } from '../lib/supabase';      // service role (ignora RLS)
Usar supabaseAdmin apenas em operações do scheduler e admin endpoints

import { gemini } from '../lib/gemini';
await gemini.generateContent({ contents: [...] })
Embedding: await gemini.embedContent({ content: { parts: [{ text }] } })

POST ${UAZAPI_URL}/message/sendText
Body: { phone: '55119...', message: 'texto' }
Headers: { apikey: UAZAPI_KEY }

try { ... } catch (err) {
  logger.error('contexto', err);
  res.writeHead(500); res.end(JSON.stringify({ error: 'mensagem segura' }));
}

task.sql:
-- ============================================================ -- ENUMS -- ============================================================ CREATE TYPE ticket_status AS ENUM ( 'open', 'ai_triaged', 'in_progress', 'waiting_tenant', 'escalated', 'resolved', 'closed', 'reopened', 'ai_responding', 'ai_resolved', 'needs_human', 'learning' ); CREATE TYPE ticket_priority AS ENUM ('low', 'medium', 'high', 'critical'); CREATE TYPE ticket_channel AS ENUM ('portal', 'whatsapp', 'email', 'admin'); CREATE TYPE audit_action AS ENUM ( 'created', 'status_changed', 'priority_changed', 'assigned', 'message_added', 'attachment_added', 'sla_breached', 'escalated', 'resolved', 'closed', 'reopened', 'csat_rated' );
-- ============================================================ -- CATEGORIAS DE TICKET -- ============================================================ CREATE TABLE ticket_categories ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, keywords TEXT[] DEFAULT '{}', color_hex TEXT DEFAULT '#6366f1', icon TEXT DEFAULT 'tag', active BOOLEAN NOT NULL DEFAULT TRUE );
INSERT INTO ticket_categories (name, keywords, color_hex, icon) VALUES ('Conectores', ARRAY['sincronizar','conector','google','facebook','tripadvisor'], '#3b82f6', 'plug'), ('Relatórios', ARRAY['relatório','pdf','exportar','gráfico'], '#8b5cf6', 'chart'), ('Cobrança', ARRAY['pagamento','fatura','assinatura','plano','cobrado'], '#f59e0b', 'credit-card'), ('Acesso', ARRAY['login','senha','acesso','conta','email'], '#ef4444', 'lock'), ('Funcionalidade', ARRAY['bug','erro','não funciona','problema','falha'], '#10b981', 'bug'), ('Dúvida', ARRAY['como','dúvida','tutorial','explicar','ajuda'], '#6b7280', 'help-circle');
-- ============================================================ -- REGRAS DE SLA POR PLANO -- ============================================================ CREATE TABLE ticket_sla_rules ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), plan_id UUID REFERENCES plans(id) ON DELETE SET NULL, priority ticket_priority NOT NULL, first_response_mins INTEGER NOT NULL, resolution_mins INTEGER NOT NULL, escalation_mins INTEGER NOT NULL, escalation_level SMALLINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (plan_id, priority) );
INSERT INTO ticket_sla_rules (plan_id, priority, first_response_mins, resolution_mins, escalation_mins, escalation_level) VALUES (NULL, 'low', 480, 4320, 1440, 1), (NULL, 'medium', 240, 2880, 720, 1), (NULL, 'high', 60, 1440, 360, 2), (NULL, 'critical', 30, 480, 120, 3);
-- ============================================================ -- TABELA PRINCIPAL DE TICKETS -- ============================================================ CREATE TABLE support_tickets ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, created_by UUID NOT NULL REFERENCES auth.users(id), assigned_to UUID REFERENCES auth.users(id), ticket_number SERIAL, subject TEXT NOT NULL, description TEXT NOT NULL, channel ticket_channel NOT NULL DEFAULT 'portal', category_id UUID REFERENCES ticket_categories(id), tags TEXT[] DEFAULT '{}', priority ticket_priority NOT NULL DEFAULT 'medium',
-- Campos preenchidos pela IA na triagem ai_sentiment TEXT CHECK (ai_sentiment IN ('positive','neutral','negative','frustrated')), ai_summary TEXT,
-- Campos do Agente de IA Autônomo ai_confidence NUMERIC(4,3), ai_attempt_count SMALLINT NOT NULL DEFAULT 0, ai_doc_used_id UUID, -- FK adicionada na migration 011 ai_handled BOOLEAN NOT NULL DEFAULT FALSE, ai_draft_response TEXT,
-- Estado status ticket_status NOT NULL DEFAULT 'open', is_sla_breached BOOLEAN NOT NULL DEFAULT FALSE, escalation_level SMALLINT NOT NULL DEFAULT 0,
-- Timestamps created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), first_response_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, closed_at TIMESTAMPTZ, sla_deadline TIMESTAMPTZ,
-- CSAT csat_score SMALLINT CHECK (csat_score BETWEEN 1 AND 5), csat_comment TEXT, csat_at TIMESTAMPTZ,
-- WhatsApp whatsapp_thread_id TEXT,
CONSTRAINT ticket_number_tenant_unique UNIQUE (tenant_id, ticket_number) );
CREATE INDEX idx_tickets_tenant_status ON support_tickets(tenant_id, status); CREATE INDEX idx_tickets_assigned ON support_tickets(assigned_to) WHERE assigned_to IS NOT NULL; CREATE INDEX idx_tickets_sla_deadline ON support_tickets(sla_deadline) WHERE status NOT IN ('resolved','closed','ai_resolved'); CREATE INDEX idx_tickets_created_at ON support_tickets(created_at DESC);
-- ============================================================ -- MENSAGENS / THREAD -- ============================================================ CREATE TABLE ticket_messages ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, author_id UUID REFERENCES auth.users(id), author_role TEXT NOT NULL CHECK (author_role IN ('tenant_user','agent','ai','system')), body TEXT NOT NULL, is_internal BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_messages_ticket ON ticket_messages(ticket_id, created_at);
-- ============================================================ -- ANEXOS -- ============================================================ CREATE TABLE ticket_attachments ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, message_id UUID REFERENCES ticket_messages(id) ON DELETE SET NULL, uploaded_by UUID NOT NULL REFERENCES auth.users(id), filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, storage_path TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
-- ============================================================ -- AUDITORIA IMUTÁVEL -- ============================================================ CREATE TABLE ticket_audit_log ( id BIGSERIAL PRIMARY KEY, ticket_id UUID NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, actor_id UUID REFERENCES auth.users(id), actor_role TEXT NOT NULL DEFAULT 'system', action audit_action NOT NULL, from_value TEXT, to_value TEXT, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_audit_ticket ON ticket_audit_log(ticket_id, created_at);
-- ============================================================ -- RLS -- ============================================================ ALTER TABLE support_tickets ENABLE ROW LEVEL SECURITY; ALTER TABLE ticket_messages ENABLE ROW LEVEL SECURITY; ALTER TABLE ticket_attachments ENABLE ROW LEVEL SECURITY; ALTER TABLE ticket_audit_log ENABLE ROW LEVEL SECURITY;
-- Tenants veem apenas seus tickets; admins veem tudo CREATE POLICY tickets_select ON support_tickets FOR SELECT USING (tenant_id = auth_tenant_id() OR is_admin());
CREATE POLICY tickets_insert ON support_tickets FOR INSERT WITH CHECK (tenant_id = auth_tenant_id());
-- Mensagens: tenant vê apenas mensagens públicas dos seus tickets CREATE POLICY messages_select ON ticket_messages FOR SELECT USING ( EXISTS ( SELECT 1 FROM support_tickets t WHERE t.id = ticket_id AND (t.tenant_id = auth_tenant_id() OR is_admin()) ) AND (is_internal = FALSE OR is_admin()) );
-- Audit log: somente admins leem; nenhum role faz update/delete CREATE POLICY audit_select ON ticket_audit_log FOR SELECT USING (is_admin());
-- ============================================================ -- TRIGGERS updated_at -- ============================================================ CREATE TRIGGER set_ticket_updated_at BEFORE UPDATE ON support_tickets FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- pgvector já disponível no Supabase CREATE EXTENSION IF NOT EXISTS vector;
-- ============================================================ -- DOCUMENTOS DE CONHECIMENTO (gerados automaticamente pela IA) -- ============================================================ CREATE TABLE support_knowledge_docs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID REFERENCES ticket_categories(id), title TEXT NOT NULL, problem_description TEXT NOT NULL, problem_variants TEXT[] DEFAULT '{}', solution_steps JSONB NOT NULL DEFAULT '[]', solution_summary TEXT NOT NULL, tags TEXT[] DEFAULT '{}', keywords TEXT[] DEFAULT '{}', source_ticket_ids UUID[] DEFAULT '{}', resolution_count INTEGER NOT NULL DEFAULT 1, avg_csat NUMERIC(3,2), confidence_score NUMERIC(4,3) NOT NULL DEFAULT 0.700, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','archived','needs_review')), auto_published BOOLEAN NOT NULL DEFAULT FALSE, reviewed_by UUID REFERENCES auth.users(id), reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_kb_docs_category ON support_knowledge_docs(category_id) WHERE status = 'active'; CREATE INDEX idx_kb_docs_status ON support_knowledge_docs(status);
-- FK da tabela de tickets para o doc usado pela IA ALTER TABLE support_tickets ADD CONSTRAINT fk_ticket_ai_doc FOREIGN KEY (ai_doc_used_id) REFERENCES support_knowledge_docs(id) ON DELETE SET NULL;
-- ============================================================ -- EMBEDDINGS VETORIAIS (768 dims — Gemini text-embedding-004) -- ============================================================ CREATE TABLE support_knowledge_embeddings ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), doc_id UUID NOT NULL REFERENCES support_knowledge_docs(id) ON DELETE CASCADE, content TEXT NOT NULL, embedding vector(768) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
-- HNSW index — busca de similaridade cosine em <10ms para KB de até 100k docs CREATE INDEX idx_kb_embeddings_hnsw ON support_knowledge_embeddings USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);
-- ============================================================ -- FUNÇÃO DE BUSCA SEMÂNTICA -- ============================================================ CREATE OR REPLACE FUNCTION search_knowledge( query_embedding vector(768), match_threshold FLOAT DEFAULT 0.65, match_count INT DEFAULT 5, filter_category UUID DEFAULT NULL ) RETURNS TABLE ( doc_id UUID, title TEXT, solution_summary TEXT, solution_steps JSONB, similarity FLOAT, confidence_score NUMERIC, resolution_count INT ) LANGUAGE sql STABLE AS $$ SELECT d.id, d.title, d.solution_summary, d.solution_steps, 1 - (e.embedding <=> query_embedding) AS similarity, d.confidence_score, d.resolution_count FROM support_knowledge_embeddings e JOIN support_knowledge_docs d ON d.id = e.doc_id WHERE d.status = 'active' AND (filter_category IS NULL OR d.category_id = filter_category) AND 1 - (e.embedding <=> query_embedding) >= match_threshold ORDER BY e.embedding <=> query_embedding LIMIT match_count; $$;
-- ============================================================ -- INTERAÇÕES DA IA (log de cada ação do agente) -- ============================================================ CREATE TABLE ticket_ai_interactions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, interaction_type TEXT NOT NULL CHECK (interaction_type IN ( 'triage','knowledge_search','autonomous_response', 'draft_suggestion','satisfaction_check','auto_close', 'escalation_decision','learning_extraction' )), query_text TEXT, matched_doc_ids UUID[] DEFAULT '{}', top_similarity NUMERIC(4,3), confidence_tier TEXT CHECK (confidence_tier IN ('T1','T2','T3')), generated_response TEXT, model_used TEXT DEFAULT 'gemini-flash', prompt_tokens INTEGER, completion_tokens INTEGER, outcome TEXT CHECK (outcome IN ( 'sent_autonomously','draft_shown','routed_to_human', 'customer_satisfied','customer_not_satisfied','timeout_closed', 'knowledge_extracted','knowledge_updated' )), outcome_csat SMALLINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_ai_interactions_ticket ON ticket_ai_interactions(ticket_id, created_at);
-- ============================================================ -- FILA DE APRENDIZADO -- ============================================================ CREATE TABLE support_learning_queue ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE UNIQUE, priority SMALLINT NOT NULL DEFAULT 5, attempts SMALLINT NOT NULL DEFAULT 0, last_error TEXT, scheduled_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), processed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_learning_queue_pending ON support_learning_queue(priority, scheduled_at) WHERE processed_at IS NULL;
-- trigger updated_at para knowledge_docs CREATE TRIGGER set_kb_doc_updated_at BEFORE UPDATE ON support_knowledge_docs FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

task.interface:
export interface KBSearchResult {
  docId: string;
  title: string;
  solutionSummary: string;
  solutionSteps: Array<{ step: number; text: string; code?: string }>;
  similarity: number;
  confidenceScore: number;
  resolutionCount: number;
}

export class EmbeddingService {
  async generateEmbedding(text: string): Promise<number[]>
  async searchKnowledge(query: string, opts?: {
    threshold?: number;   // default 0.65
    count?: number;       // default 5
    categoryId?: string;
  }): Promise<KBSearchResult[]>
  async upsertDocEmbedding(docId: string, content: string): Promise<void>
}

task.promptTemplate:
Você é um agente de triagem de suporte técnico para a Reputei, uma plataforma SaaS de monitoramento de reputação online.

Analise o ticket abaixo e retorne SOMENTE um JSON válido (sem markdown, sem explicações):

{
  "priority": "low" | "medium" | "high" | "critical",
  "category_name": "<uma das categorias listadas abaixo>",
  "sentiment": "positive" | "neutral" | "negative" | "frustrated",
  "summary": "<resumo em português, máx 120 caracteres>"
}

Ticket:
Assunto: {{subject}}
Descrição: {{description}}
Canal: {{channel}}
Plano do tenant: {{plan_name}}

Categorias disponíveis: {{categories_list}}

Critérios de prioridade:
- critical: sistema totalmente inacessível, perda de dados, impacto financeiro imediato
- high: funcionalidade principal quebrada, SLA de clientes afetado
- medium: funcionalidade degradada, workaround possível
- low: dúvida, melhoria, solicitação sem urgência

JSON:

method.promptTemplate:
Você é o assistente de suporte técnico da Reputei, uma plataforma de monitoramento de reputação online. Responda ao cliente de forma clara, empática e objetiva em português brasileiro.
== TICKET == Assunto: {{ticket.subject}} Descrição: {{ticket.description}} Plano: {{tenant.plan_name}}
== BASE DE CONHECIMENTO — SOLUÇÕES DISPONÍVEIS == {{kbResults.map((r, i) => `[${i+1}] ${r.title}\n${r.solutionSummary}`).join('\n\n')}}
== INSTRUÇÕES == - Use a solução mais relevante para responder - Seja direto e conciso (máximo 5 parágrafos) - Se houver passos, use lista numerada - Termine com: "Isso resolveu o seu problema?" - NÃO mencione base de conhecimento, IA ou sistema interno - Se não tiver certeza, use "normalmente" ou "geralmente" - Tom: profissional mas acessível
Resposta:

method.extractionPrompt:
Você é um engenheiro de suporte técnico construindo uma base de conhecimento a partir de tickets resolvidos.

== THREAD DO TICKET ==
Categoria: {{category}}
Assunto: {{subject}}

{{formattedThread}}

== TAREFA ==
Extraia um documento de conhecimento em JSON. Retorne SOMENTE o JSON, sem markdown.

{
  "title": "título descritivo do problema em até 80 caracteres",
  "problem_description": "descrição canônica do problema em 2-3 frases objetivas",
  "problem_variants": ["outras formas como este problema pode ser descrito pelo usuário"],
  "solution_summary": "resposta completa e direta ao problema, em linguagem natural, 2-4 parágrafos, pronta para ser enviada a um cliente",
  "solution_steps": [
    { "step": 1, "text": "descrição do passo", "code": "valor ou comando opcional" }
  ],
  "keywords": ["palavras-chave relevantes para busca semântica"],
  "tags": ["tags de categoria"]
}

Regras:
- Foque na solução definitiva, não no diagnóstico
- solution_summary deve soar natural, como se fosse escrita por um humano para um cliente
- Se a solução exigir acesso administrativo, deixe claro
- Use português brasileiro

component.aiResponseActions:
Após mensagem com author_role='ai': exibe dois botões inline no chat:
✓ "Isso resolveu meu problema" → POST /api/support/:id/confirm-resolution { csat_score: null }
✗ "Ainda preciso de ajuda" → foca no campo de resposta para o usuário digitar
